CREATE DATABASE IF NOT EXISTS philsurin CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE philsurin;
CREATE TABLE users (id INT AUTO_INCREMENT PRIMARY KEY, username VARCHAR(50) UNIQUE NOT NULL, password_hash VARCHAR(255) NOT NULL, role VARCHAR(50) NOT NULL DEFAULT 'viewer', active TINYINT(1) NOT NULL DEFAULT 1);
CREATE TABLE varieties (id INT AUTO_INCREMENT PRIMARY KEY, code VARCHAR(20) UNIQUE NOT NULL, name VARCHAR(150) NOT NULL, description TEXT);
CREATE TABLE validations (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, variety_id INT NOT NULL, result ENUM('Validated','Needs review','Rejected') NOT NULL, notes TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users(id), FOREIGN KEY (variety_id) REFERENCES varieties(id));
